css:
:root {
  /* Jungle Canopy Theme - layered greens and dappled light */
  --bg-primary: #f2f8f1;
  --bg-alt: #e0f0df;
  --bg-hover: #c9e6c3;
  --text-primary: #1e3a28;
  --text-secondary: #2f5e3f;
  --border: #7cb587;
  --accent: #3f9e60;
  --accent-hover: #2f7b49;
  --shadow: 0 10px 30px rgba(31, 94, 66, 0.18);
}

[data-theme="dark"] {
  --bg-primary: #0d1a12;
  --bg-alt: #0f2417;
  --bg-hover: #153420;
  --text-primary: #d8f2df;
  --text-secondary: #a6d4b2;
  --border: #2f7b49;
  --accent: #60c183;
  --accent-hover: #7cd8a0;
  --shadow: 0 12px 38px rgba(96, 193, 131, 0.28);
}

body {
  background: radial-gradient(circle at 20% 20%, rgba(124, 181, 135, 0.08), transparent 25%),
              radial-gradient(circle at 80% 0%, rgba(96, 193, 131, 0.1), transparent 25%),
              var(--bg-primary);
}

.card {
  border: 1px solid var(--border);
  box-shadow: var(--shadow);
  background: linear-gradient(160deg, var(--bg-alt) 0%, var(--bg-primary) 100%);
  position: relative;
  overflow: hidden;
}

.card::after {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 30% 10%, rgba(63, 158, 96, 0.12), transparent 30%),
              radial-gradient(circle at 70% 90%, rgba(47, 123, 73, 0.08), transparent 30%);
  pointer-events: none;
}

.tag {
  background: rgba(63, 158, 96, 0.12);
  color: var(--text-primary);
  border: 1px solid var(--accent);
}
